const RATES = { DE: 0.19, US: 0.07 };

/**
 * @returns {number} 0 when the country is not in the rate table
 */
export function rateFor(country) {
  return RATES[country] ?? 0;
}

/**
 * @returns {number} rounded half-up to whole cents
 */
export function withTax(cents, country) {
  return Math.round(cents * (1 + rateFor(country)));
}
```

